# The diagnostic catalog carries control-specific rationales, never a generic
# instruction to apply every hardening option or break desktop compatibility.
from .check_catalog import RULES as CATALOG_RULES
for rule in CATALOG_RULES:
    GUIDANCE[rule.id]=(["Inspect "+rule.label+" in the recorded evidence.",rule.reason,"Review upstream documentation and compatibility before changing this control."],"Rerun the same profile and verify this exact control; configuration facts do not establish whole-machine safety.")


def instructions(check_id, status):
    steps, verification = GUIDANCE.get(check_id, (['Review the evidence and identify the responsible application or administrator before making changes.'], 'Repeat the relevant check and confirm the intended behavior.'))
    if status == 'pass':
        steps = ['No change is indicated by this observation.'] + steps
    elif status in ('unavailable', 'error'):
        steps = ['This check could not establish the state; do not treat it as a confirmed fault.'] + steps
    return steps[:5], verification
